// Decide what happens on this run. Reads every appointment row and emits tagged items:
//   action = "reminder24" -> appointment starts in 23-25 hours, not yet reminded
//   action = "reminder2h"  -> appointment starts in 1-3 hours, not yet reminded
//   action = "digest"     -> ONE item for the owner listing tomorrow's bookings
//                            (only on the run that lands in your digest hour)
// Everything else is dropped silently — no item, no email, no noise.
const HOUR_MS = 60 * 60 * 1000;
const now = Date.now();
const items = $input.all();
if (!items.length) return [];
const cfg = items[0].json;
const digestHour = Number(cfg.config_digest_hour || 8);
const out = [];
const tomorrow = [];
for (const item of items) {
  const j = item.json;
  if (String(j['Status'] || '').trim().toLowerCase() === 'cancelled') continue;
  const start = new Date(`${j['Appointment Date']}T${j['Appointment Time'] || '09:00'}:00`).getTime();
  if (isNaN(start)) continue;
  const hoursUntil = (start - now) / HOUR_MS;
  if (hoursUntil > 23 && hoursUntil <= 25 && !String(j['Reminder 24h Sent'] || '').trim()) {
    out.push({ json: { ...j, action: 'reminder24' } });
  }
  if (hoursUntil > 1 && hoursUntil <= 3 && !String(j['Reminder 2h Sent'] || '').trim()) {
    out.push({ json: { ...j, action: 'reminder2h' } });
  }
  const startDay = new Date(start); startDay.setHours(0, 0, 0, 0);
  const tomorrowDay = new Date(now + 24 * HOUR_MS); tomorrowDay.setHours(0, 0, 0, 0);
  if (startDay.getTime() === tomorrowDay.getTime()) tomorrow.push(j);
}
if (new Date().getHours() === digestHour && tomorrow.length) {
  const lines = tomorrow
    .map(a => `- ${a['Appointment Time']} - ${a['Client Name']} (${a['Service']})`)
    .join('\n');
  out.push({ json: { action: 'digest', digest_text: lines, digest_count: tomorrow.length,
                     config_owner_email: cfg.config_owner_email,
                     config_business_name: cfg.config_business_name } });
}
return out;

